        A = draw(st.lists(st.integers(1, n), min_size=n, max_size=n))
        B = draw(st.lists(
            st.one_of(st.integers(1, n), st.sampled_from(A)),
            min_size=n, max_size=n))
        lines.append(f"{n} {k}")
        lines.append(" ".join(map(str, A)))
        lines.append(" ".join(map(str, B)))
    return "\n".join(lines) + "\n"

