    pos = 0
    T = int(t[pos]); pos += 1
    out = []
    for _ in range(T):
        n = int(t[pos]); k = int(t[pos + 1]); pos += 2
        A = tuple(int(x) for x in t[pos:pos + n]); pos += n
        B = tuple(int(x) for x in t[pos:pos + n]); pos += n
        # Literal BFS over all reachable arrays.
        seen = {A}
        dq = deque([A])
        found = A == B
        while dq and not found:
            cur = dq.popleft()
            for i in range(n):
                for j in range(n):
                    if abs(i - j) <= k and cur[i] != cur[j]:
                        nxt = list(cur)
                        nxt[i] = cur[j]
                        nxt = tuple(nxt)
                        if nxt not in seen:
                            seen.add(nxt)
                            if nxt == B:
                                found = True
                            dq.append(nxt)
        out.append("Yes" if found else "No")
    return "\n".join(out)
