        lines.append(f"{n} {k}")
        lines.append(" ".join(map(str, A)))
        lines.append(" ".join(map(str, B)))
    return "\n".join(lines) + "\n"


def _parse(inp):
    t = inp.split()
    pos = 0
    T = int(t[pos]); pos += 1
    cases = []
    for _ in range(T):
        n = int(t[pos]); k = int(t[pos + 1]); pos += 2
        A = [int(x) for x in t[pos:pos + n]]; pos += n
        B = [int(x) for x in t[pos:pos + n]]; pos += n
        cases.append((n, k, A, B))
    if pos != len(t):
        raise ValueError("extra tokens")
    return T, cases


def validate(inp: str) -> bool:
    try:
        T, cases = _parse(inp)
        if not (1 <= T <= 125000):
            return False
        total = 0
        for n, k, A, B in cases:
            if not (1 <= k < n):
                return False
            if not (1 <= n <= 250000):
                return False
            total += n
            if len(A) != n or len(B) != n:
                return False
            if not all(1 <= x <= n for x in A + B):
                return False
        if total > 250000:
            return False
        return True
    except Exception:
        return False


def _reachable(n, k, A, B):
    start = tuple(A)
    target = tuple(B)
    if start == target:
        return True
    seen = {start}
    stack = [start]
    while stack:
        s = stack.pop()
        for i in range(n):
            for j in range(n):
                if abs(i - j) <= k and s[j] != s[i]:
                    new = list(s)
                    new[i] = s[j]
                    ns = tuple(new)
                    if ns == target:
                        return True
                    if ns not in seen:
                        seen.add(ns)
                        stack.append(ns)
    return False


def ref(inp: str) -> str:
    T, cases = _parse(inp)
    out = []
    for n, k, A, B in cases:
        out.append("Yes" if _reachable(n, k, A, B) else "No")
    return "\n".join(out) + "\n"

